        uint balBefore = c.getBalance(address(this));
        uint cEthBefore = address(c).balance;
        uint thisEthBefore = address(this).balance;

        c.addToBalance{value: amount}();

        uint balAfterDeposit = c.getBalance(address(this));
        uint cEthAfterDeposit = address(c).balance;

        bool withdrawReverted = false;
