    }

    function run(address who) public payable {
        require(who != address(0));

        uint priorRecorded = c.getBalance(who);
        uint priorContractEther = address(c).balance;
        bool zeroBefore = (priorRecorded == 0);

        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterRecorded = c.getBalance(who);
        uint afterContractEther = address(c).balance;

        if (zeroBefore) {
            assert(!reverted);
            assert(afterRecorded == priorRecorded);
            assert(afterContractEther == priorContractEther);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

