contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    uint256 private deposited;

    function run(address user, uint256 depositAmount) public payable {
        require(user == address(this), "user must be the test contract");
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        c.addToBalance{value: depositAmount}();
        uint256 balBefore = c.getBalance(address(this));
        uint256 etherBefore = address(this).balance;

        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.getBalance(address(this));
        uint256 etherGained = address(this).balance - etherBefore;

        if (!reverted && balBefore > 0) {
            assert(balAfter + etherGained >= balBefore);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}
